function callTimeoutV41(side,reason='MANUAL'){if(!game||!side||(game.timeouts?.[side]||0)<=0)return false;game.timeouts[side]--;for(const p of lineup(side))game.energy[p.id]=clamp((game.energy[p.id]||70)+3.5,28,100);for(const p of lineup(side==='home'?'away':'home'))game.energy[p.id]=clamp((game.energy[p.id]||70)+1.25,28,100);game.scoreRun={side:null,points:0};game.timeoutNotice={side,reason,coach:coachStaffV41(rotationForSide(side).team).name};addFeed(`${team(rotationForSide(side).team).abbr} TIMEOUT — ${reason}.`,side,false);logCoachV41(side,'TIMEOUT',reason);if(side===userSideV41())stopLive();return true}
