function pregameCoachingPanelV41(){const p=coachingPrefsV41(),c=coachStaffV41(save.userTeam),gm=coachSkillV41(save.userTeam),rot=coachSkillV41(save.userTeam,'rotations');return `<section class="coachPrep"><div class="coachPrepHead"><div><span>GAME DAY · COACHING CONTROL</span><b>${c.name}</b><small>${c.scheme?.label||'BALANCED'} · Game Management ${gm} · Rotations ${rot}</small></div><b class="coachRating">${gm}<em>SIM COACH</em></b></div><div class="coachModeGrid">${Object.entries(COACH_MODES_V41).map(([k,v])=>`<button data-coach-mode="${k}" class="${p.mode===k?'active':''}"><b>${v.label}</b><small>${v.sub}</small></button>`).join('')}</div><div class="coachSubhead"><b>ROTATION PLAN</b><span>APPLIES BEFORE TIP</span></div><div class="rotationPlanGrid">${Object.entries(ROTATION_PLANS_V41).map(([k,v])=>`<button data-rotation-plan="${k}" class="${p.rotationPlan===k?'active':''}">${v}</button>`).join('')}</div><p class="coachAutoNote">Full Auto preserves a hands-off Game Day. Assisted pauses for major decisions. Manual keeps substitutions under your control while injury caps and foul-outs remain mandatory.</p></section>`}
function liveModeV41(mode){if(!COACH_MODES_V41[mode]||!game)return;game.coachingMode=mode;coachingPrefsV41().mode=mode;if(mode!=='manual'&&game.manualOverride?.[userSideV41()]!==true)game.manualLineup[userSideV41()]=null;if(mode==='manual'&&!game.manualLineup[userSideV41()])game.manualLineup[userSideV41()]=scheduledLineup(userSideV41()).map(x=>({...x}));persistSave();game.lastMinute=-1;syncLineups(true);render()}
function decisionPanelV41(){const d=game?.decision;if(!d)return'';return `<section class="decisionDesk"><span>ASSISTED COACHING · DECISION</span><h3>${d.title}</h3><p>${d.text}</p><div class="decisionActions">${d.type==='run'?'<button data-decision="timeout">CALL TIMEOUT</button><button data-decision="adjust">ADJUST WITHOUT TIMEOUT</button>':'<button data-decision="protect">PROTECT PLAYER</button><button data-decision="keep">KEEP HIM IN</button>'}</div></section>`}
function halftimePanelV41(){const us=userSideV41(),os=us==='home'?'away':'home',u=teamTotalsV41(us),o=teamTotalsV41(os),rec=recommendationV41(),c=coachStaffV41(save.userTeam);return `<section class="halftimeDesk"><span>HALFTIME · COACH'S ROOM</span><h3>${team(gameDef.away).abbr} ${game.awayScore} · ${team(gameDef.home).abbr} ${game.homeScore}</h3><div class="halftimeScore">${us==='home'?game.homeScore:game.awayScore}–${us==='home'?game.awayScore:game.homeScore}</div><div class="halftimeStats"><div><span>YOUR 3PT</span><b>${u.tpm}/${u.tpa}</b></div><div><span>TURNOVERS</span><b>${u.tov}–${o.tov}</b></div><div><span>FOULS</span><b>${u.pf}–${o.pf}</b></div></div><div class="assistantCall"><b>${assistantNameV41(save.userTeam)} · ASSISTANT NOTE</b><span>${rec.text} Recommended: ${OFFENSE_V41[rec.offense]} / ${DEFENSE_V41[rec.defense]}.</span></div><div class="halftimeChoices"><button data-halftime="recommended" class="active">TAKE RECOMMENDATION</button><button data-halftime="attack">PUSH THE PACE</button><button data-halftime="shoot">MORE THREES</button><button data-halftime="defend">PROTECT PAINT</button><button data-halftime="keep">KEEP PLAN</button></div><p>${c.name} · simulated coaching decision support.</p></section>`}
function timeoutBannerV41(){const n=game?.timeoutNotice;if(!n)return'';const a=rotationForSide(n.side).team;return `<div class="timeoutBanner">TIMEOUT · ${team(a).abbr} · ${n.coach} · ${n.reason}</div>`}
function coachDeskV41(){const us=userSideV41();if(!game||!us)return'';const os=us==='home'?'away':'home',a=rotationForSide(us).team,c=coachStaffV41(a),t=game.tactics[us],line=scheduledLineup(us),lineIds=new Set(line.map(x=>x.id)),bench=rotationForSide(us).players.filter(p=>!lineIds.has(p.id)&&!game.gameInjured[p.id]&&(game.stats[p.id]?.pf||0)<6),opp=lineup(os),rec=recommendationV41();return `<details class="coachDesk" ${game.coachingMode==='manual'||game.decision||game.halftimePending?'open':''}><summary class="coachDeskHead"><div><span>COACH DESK · ${COACH_MODES_V41[game.coachingMode].label}</span><b>${c.name}</b><small>${OFFENSE_V41[t.offense]} · ${DEFENSE_V41[t.defense]}</small></div><b class="coachRating">${game.timeouts[us]}<em>TIMEOUTS</em></b></summary><div class="coachModeGrid">${Object.entries(COACH_MODES_V41).map(([k,v])=>`<button data-live-mode="${k}" class="${game.coachingMode===k?'active':''}">${v.label}</button>`).join('')}</div><div class="coachStatus"><div><span>OFFENSE</span><b>${OFFENSE_V41[t.offense]}</b></div><div><span>DEFENSE</span><b>${DEFENSE_V41[t.defense]}</b></div><div><span>LATE GAME</span><b>${LATE_V41[t.late]}</b></div></div>${game.coachingMode==='full_auto'?`<div class="assistantCall"><b>AUTO COACHING ACTIVE</b><span>${c.name} will handle timeouts, substitutions and tactical adjustments. Switch modes at any time.</span></div>`:`<div class="coachSubhead"><b>OFFENSIVE EMPHASIS</b><span>${assistantNameV41(a)}: ${rec.text}</span></div><div class="tacticRail">${Object.entries(OFFENSE_V41).map(([k,v])=>`<button data-coach-off="${k}" class="${t.offense===k?'active':''}">${v}</button>`).join('')}</div><div class="coachSubhead"><b>DEFENSIVE COVERAGE</b><span>BOUNDED TACTICAL EFFECT</span></div><div class="tacticRail">${Object.entries(DEFENSE_V41).map(([k,v])=>`<button data-coach-def="${k}" class="${t.defense===k?'active':''}">${v}</button>`).join('')}</div><div class="coachSubhead"><b>LATE GAME</b><span>FINAL 45 SECONDS</span></div><div class="tacticRail lateRail">${Object.entries(LATE_V41).map(([k,v])=>`<button data-coach-late="${k}" class="${t.late===k?'active':''}">${v}</button>`).join('')}</div><div class="coachQuick"><button class="timeout" id="callTimeout" ${game.timeouts[us]<=0?'disabled':''}>CALL TIMEOUT · ${game.timeouts[us]} LEFT</button><button id="resumeAuto">RESUME AUTO SUBS</button></div><div class="coachSubhead"><b>LIVE SUBSTITUTION</b><span>${game.manualOverride[us]?'MANUAL LINEUP ACTIVE':game.coachingMode==='manual'?'MANUAL MODE':'AUTO SCHEDULE ACTIVE'}</span></div><div class="subControl"><select id="subOut">${line.map(x=>{const p=byId.get(x.id);return `<option value="${p.id}">${lastName(p)} · ${game.stats[p.id].pf} PF · ${pct(game.energy[p.id])}%</option>`}).join('')}</select><select id="subIn">${bench.map(p=>`<option value="${p.id}">${lastName(p)} · ${game.stats[p.id].pf} PF · ${pct(game.energy[p.id])}%</option>`).join('')}</select><button id="makeSub" ${bench.length?'':'disabled'}>SUB</button></div><div class="coachSubhead"><b>PRIMARY MATCHUP</b><span>ASSIGN A DEFENDER TO A TARGET</span></div><div class="matchupControl"><select id="matchDef">${rotationForSide(us).players.filter(p=>(game.stats[p.id]?.pf||0)<6).map(p=>`<option value="${p.id}" ${game.matchups[us]?.defenderId===p.id?'selected':''}>${lastName(p)} · D ${Math.round((rating(p,'perimeter_defense')+rating(p,'interior_defense'))/2)}</option>`).join('')}</select><select id="matchTarget">${rotationForSide(os).players.map(p=>`<option value="${p.id}" ${game.matchups[us]?.targetId===p.id?'selected':''}>${lastName(p)} · ${overall(p)} OVR</option>`).join('')}</select><button id="setMatchup">ASSIGN</button></div>`}<p class="coachAutoNote">Tactical effects are intentionally bounded. Coaching changes shot profile, pace, pressure and decision quality; it does not replace player ratings or guarantee outcomes.</p></details>`}

function topPlayers(a,n=2){return teamPlayers(a).sort((x,y)=>overall(y)-overall(x)).slice(0,n)}
function rotationRow(rot,p,i){const st=rot.starterIds.has(p.id),slot=st?(rot.slotMap.get(p.id)||'ST'):'B'+(i-4),cond=healthConditionV40(p),ret=healthReturnV40(p);return `<div class="rotRow"><div class="rotSlot">${slot}</div>${img(p)}<div><div class="rotName">${p.name}</div><div class="rotMeta">${p.positions.join('/')} · ${overall(p)} OVR · ${cond}% CONDITION${ret?' · RTP':''}</div></div><div class="rotMin"><b>${rot.targets.get(p.id)}</b><span>${ret?'MED CAP':'TARGET'}</span></div></div>`}
function rotationCard(rot,side){const t=team(rot.team),user=save?.userTeam===rot.team;return `<section class="rotationTeam" style="--rot:${t.primary_color}"><div class="rotHead">${logo(t)}<div><strong>${t.name}</strong><span>${user?'YOUR ROTATION':'CPU ROTATION'} · ${rot.players.length} ACTIVE</span></div></div><div class="rotRows">${rot.players.map((p,i)=>rotationRow(rot,p,i)).join('')}</div></section>`}
function unavailablePlayers(a){return players.filter(p=>currentTeam(p)===a&&currentStatus(p)==='active'&&injuryFor(p))}
function availabilityPanel(a){const t=team(a),alerts=players.filter(p=>currentTeam(p)===a&&['active','two_way'].includes(currentStatus(p))).map(p=>({p,i:injuryFor(p),r:healthReturnV40(p),plan:healthPlanV40(p),fat:+healthEntryV40(p).fatigue||0})).filter(x=>x.i||x.r||x.plan?.mode==='rest'||x.fat>=62).sort((x,y)=>(y.i?100:0)+y.fat-((x.i?100:0)+x.fat));return `<section class="availabilityPanel" style="--avail:${t.primary_color}"><div>${logo(t)}<strong>${t.abbr}</strong><span>${alerts.length?`${alerts.length} HEALTH ALERT${alerts.length===1?'':'S'}`:'FULL STRENGTH'}</span></div>${alerts.length?`<div class="availabilityStrip">${alerts.slice(0,5).map(x=>`<div>${img(x.p)}<b>${lastName(x.p)}</b><small>${x.i?`${x.i.name} · ${daysBetween(gameDef.date,x.i.return_date)}D`:x.plan?.mode==='rest'?'REST':x.r?`${x.r.cap} MIN RTP`:`${Math.round(x.fat)} FATIGUE`}</small></div>`).join('')}</div>`:'<p>No active injuries, return restrictions or heavy workload alerts.</p>'}</section>`}
function pregameScreen(){if(!save)return errorScreen('No franchise save found.','Open NBA Courtside and start a franchise first.');if(!gameDef)return errorScreen('Game not found.','Return to the GM Office and launch Game Day from your schedule or playoff bracket.');const h=team(gameDef.home),a=team(gameDef.away),hr=record(h.abbr),ar=record(a.abbr),post=isPostseason?`<div class="playoffGameBand ${gameDef.round===4?'finals':''}"><span>${postseasonLabel()}</span><strong>${postseasonStakes()}</strong></div>`:isCupFinal?`<div class="playoffGameBand finals cupFinalBand"><span>EMIRATES NBA CUP · CHAMPIONSHIP</span><strong>ONE GAME FOR THE CUP</strong></div>`:gameDef.nba_cup_group||gameDef.nba_cup?`<div class="playoffGameBand cupFinalBand"><span>EMIRATES NBA CUP</span><strong>${gameDef.cup_stage?gameDef.cup_stage.toUpperCase():gameDef.cup_group||'GROUP PLAY'}</strong></div>`:'';return `<a class="backLink" href="index.html?continue=1&v=0.48">← GM OFFICE</a><header class="topbar"><div><div class="brand">NBA COURTSIDE</div><div class="topTitle">${isPostseason?'POSTSEASON GAME DAY':isCupFinal?'NBA CUP CHAMPIONSHIP':'GAME DAY'}</div></div><div class="subtle">${shortDate(gameDef.date)}</div></header>${post}<section class="matchHero gameDayHero ${isPostseason||isCupFinal?'postseason':''}">${logo(a,'sideLogo away')}${logo(h,'sideLogo home')}<div class="matchNames"><h1>${a.name.toUpperCase()}</h1><em>${isPostseason?(postseasonSeries()?`${seriesScoreBeforeGame()?.bw??0}–${seriesScoreBeforeGame()?.aw??0}`:'WIN<br>OR<br>GO HOME'):isCupFinal?'NBA<br>CUP<br>FINAL':`${ar.w}–${ar.l}<br>${gameDef.neutral_site?'VS':'AT'}<br>${hr.w}–${hr.l}`}</em><h1 class="homeName">${h.name.toUpperCase()}</h1></div><div class="heroFaces"><div class="faceSide away">${topPlayers(a.abbr).map(p=>img(p)).join('')}</div><div class="faceSide home">${topPlayers(h.abbr).map(p=>img(p)).join('')}</div></div></section><div class="gameDayPrimaryZone"><div class="gameDayPrimaryHead"><span>DO THIS NOW</span><b>GAME DAY ACTIONS</b></div><div class="gameDayChoice"><button class="primary" id="watchGame">WATCH ${isPostseason?'PLAYOFF ':isCupFinal?'CUP FINAL ':''}GAME</button><button class="secondary" id="simNow">SIM GAME</button></div></div><div class="sectionHead"><h2>Availability</h2><span>${isPostseason?'PLAYOFF REPORT':isCupFinal?'CUP FINAL REPORT':'GAME DAY REPORT'}</span></div>${availabilityPanel(a.abbr)}${availabilityPanel(h.abbr)}${pregameCoachingPanelV41()}<div class="sectionHead"><h2>Depth Charts</h2><span>240 MINUTES EACH</span></div>${rotationCard(rotations.away,'away')}${rotationCard(rotations.home,'home')}<div class="notice"><strong>Your rotation begins from the GM roster screen.</strong> Coaching mode can alter substitutions, pace and tactical emphasis while medical caps and CBA-safe roster state remain authoritative.</div>`}
function errorScreen(title,sub){return `<a class="backLink" href="index.html?continue=1&v=0.48">← GM OFFICE</a><div class="finalHero"><div class="finalTag">NBA COURTSIDE</div><div class="finalWinner">${title}</div><div class="notice">${sub}</div></div>`}
function initStat(p){return {id:p.id,min:0,pts:0,reb:0,ast:0,stl:0,blk:0,tov:0,fgm:0,fga:0,tpm:0,tpa:0,ftm:0,fta:0,pf:0,gs:0}}
function startGame(renderNow=true,forceAuto=false){rotations={home:runtimeRotation(gameDef.home),away:runtimeRotation(gameDef.away)};const stat={};for(const p of [...rotations.home.players,...rotations.away.players])stat[p.id]=initStat(p);for(const side of ['home','away'])for(const id of rotationForSide(side).starterIds)if(stat[id])stat[id].gs=1;const energy={};for(const id of Object.keys(stat))energy[id]=pregameEnergyV40(byId.get(id));const pref=coachingPrefsV41(),mode=forceAuto?'full_auto':pref.mode;game={period:1,clock:720,homeScore:0,awayScore:0,possession:rand()<.5?'home':'away',stats:stat,energy,feed:[],moment:null,lastMinute:-1,lineups:{home:[],away:[]},gameInjured:{},pendingInjuries:[],final:false,possessions:0,coachingMode:mode,tactics:{home:defaultTacticsV41('home',mode),away:defaultTacticsV41('away',mode)},timeouts:{home:7,away:7},manualLineup:{home:null,away:null},manualOverride:{home:false,away:false},foulProtected:{home:{},away:{}},matchups:{home:null,away:null},decision:null,halftimePending:false,coachingLog:[],scoreRun:{side:null,points:0}};syncLineups(true);const us=userSideV41();if(mode==='manual'&&us){game.manualLineup[us]=scheduledLineup(us).map(x=>({...x}));game.lineups[us]=game.manualLineup[us].map(x=>x.id)}stage='game';if(renderNow)render(true)}
function minuteIndex(){if(game.period>4)return 47;return clamp((game.period-1)*12+Math.floor((720-game.clock)/60),0,47)}
function lineup(side){return game.lineups[side].map(id=>byId.get(id)).filter(Boolean)}
function scheduledLineup(side){const rot=rotationForSide(side),hard=new Set(Object.keys(game.gameInjured||{}));for(const p of rot.players){const cap=healthMinuteCapV40(p,gameDef?.date||save?.date);if(cap<48&&(game.stats?.[p.id]?.min||0)>=cap-.001)hard.add(p.id);if((game.stats?.[p.id]?.pf||0)>=6)hard.add(p.id)}const soft=new Set(rot.players.filter(p=>shouldProtectFoulV41(side,p)).map(p=>p.id));let base;if(game.manualLineup?.[side]?.length)base=game.manualLineup[side].filter(x=>!hard.has(x.id));else base=game.period>4?[...rot.players].sort((a,b)=>overall(b)-overall(a)).slice(0,5).map((p,i)=>({pos:['PG','SG','SF','PF','C'][i],id:p.id})):(rot.schedule[minuteIndex()]||rot.schedule[47]);let line=base.filter(x=>!hard.has(x.id)&&!soft.has(x.id)),used=new Set(line.map(x=>x.id));for(const pos of ['PG','SG','SF','PF','C']){if(line.some(x=>x.pos===pos))continue;let cand=rot.players.filter(p=>!hard.has(p.id)&&!soft.has(p.id)&&!used.has(p.id)).sort((a,b)=>fitScore(b,pos)-fitScore(a,pos)||overall(b)-overall(a))[0];if(!cand)cand=rot.players.filter(p=>!hard.has(p.id)&&!used.has(p.id)).sort((a,b)=>fitScore(b,pos)-fitScore(a,pos)||overall(b)-overall(a))[0];if(cand){line.push({pos,id:cand.id});used.add(cand.id)}}while(line.length<5){const cand=rot.players.filter(p=>!hard.has(p.id)&&!used.has(p.id)).sort((a,b)=>overall(b)-overall(a))[0];if(!cand)break;line.push({pos:['PG','SG','SF','PF','C'][line.length],id:cand.id});used.add(cand.id)}return line.slice(0,5)}
function addFeed(text,side,score=true){game.feed.unshift({period:game.period,clock:fmtClock(game.clock),text,side,score:score?`${game.awayScore}–${game.homeScore}`:''});game.feed=game.feed.slice(0,18)}
function syncLineups(initial=false){const idx=minuteIndex(),capReached=!initial&&['away','home'].some(side=>(game.lineups?.[side]||[]).some(id=>{const p=byId.get(id),cap=p?healthMinuteCapV40(p,gameDef?.date||save?.date):48;return cap<48&&(game.stats?.[id]?.min||0)>=cap-.001}));if(!initial&&idx===game.lastMinute&&game.period<=4&&!capReached)return;for(const side of ['away','home']){const next=scheduledLineup(side).map(x=>x.id),old=game.lineups[side]||[];if(!initial&&old.length){const incoming=next.filter(id=>!old.includes(id)).map(id=>lastName(byId.get(id))),outgoing=old.filter(id=>!next.includes(id)).map(id=>lastName(byId.get(id)));if(incoming.length)addFeed(`SUBS — ${incoming.join(', ')} in${outgoing.length?` for ${outgoing.join(', ')}`:''}.`,side,false)}game.lineups[side]=next}game.lastMinute=idx}
function simProfile(p,key,fallback=0){return p.simulation_profile?.[key]??fallback}
function shotUsage(p){return Math.max(5,simProfile(p,'fga_per36',10)+(rating(p,'shot_creation')-65)*.08)}
function weightedPick(arr,weight){let total=0;const ws=arr.map(x=>{const w=Math.max(.01,weight(x));total+=w;return w});let r=rand()*total;for(let i=0;i<arr.length;i++){r-=ws[i];if(r<=0)return arr[i]}return arr[arr.length-1]}
function teamAvg(side,key){const a=lineup(side);return a.reduce((s,p)=>s+rating(p,key),0)/Math.max(1,a.length)}
function energyAdjusted(p,key){return rating(p,key)-Math.max(0,72-(game.energy[p.id]||100))*.11}
function chooseRebounder(side,offensive=false){return weightedPick(lineup(side),p=>offensive?rating(p,'offensive_rebounding'):rating(p,'defensive_rebounding'))}
function chooseDefender(side,interior=false){return weightedPick(lineup(side),p=>interior?rating(p,'interior_defense'):rating(p,'perimeter_defense'))}
function chooseAssister(side,shooter){return weightedPick(lineup(side).filter(p=>p.id!==shooter.id),p=>simProfile(p,'ast_per36',Math.max(1,(rating(p,'playmaking')-50)/8))+rating(p,'playmaking')/30)}
// v0.19 final-season calibration: global possession/rate constants only; player evidence remains untouched.
function threeRate(p){return clamp(simProfile(p,'three_point_rate',p.tendencies?.three_point_rate??.34)*1.062,.06,.72)}
function freeThrowRate(p){return clamp(simProfile(p,'free_throw_rate',p.tendencies?.free_throw_rate??.24),.06,.65)}
function threePct(p,def){const real=p.stats_2025_26?.three_pct,base=real??(.27+(rating(p,'three_pt')-50)*.0028),pressure=(teamAvg(def,'perimeter_defense')-75)*.0012,fatigue=Math.max(0,65-(game.energy[p.id]||100))*.0008;return clamp(base-pressure-fatigue-.013,.24,.49)}
function twoPct(p,def){const old=p.stats_2025_26,prior=clamp(.49+(energyAdjusted(p,'finishing')-60)*.0032,.44,.70);let observed=null;if(old&&old.fg_pct!=null&&old.fga>0){const fga=+old.fga||0,tpa=+old.three_pa||0,fgm=(+old.fg_pct||0)*fga,tpm=(+old.three_pct||0)*tpa,twoA=Math.max(.1,fga-tpa);observed=clamp((fgm-tpm)/twoA,.38,.76)}const conf=evidenceConfidence(p),base=(observed==null?prior:observed*conf+prior*(1-conf))+.048,pressure=(teamAvg(def,'interior_defense')-75)*.00155,fatigue=Math.max(0,65-(game.energy[p.id]||100))*.00075;return clamp(base-pressure-fatigue,.40,.74)}
function ftPct(p){return clamp(p.stats_2025_26?.ft_pct??(.58+(rating(p,'free_throw')-50)*.005),.52,.96)}
function turnoverRate(p,def){const raw=simProfile(p,'tov_per36',2.2)/(simProfile(p,'fga_per36',12)+simProfile(p,'ast_per36',3)*1.8+8),base=clamp(raw*1.54,.10,.215),press=(teamAvg(def,'perimeter_defense')-72)*.00125,secure=(rating(p,'ball_security')-72)*.00085;return clamp(base+press-secure,.085,.235)}
function score(side,n){if(side==='home')game.homeScore+=n;else game.awayScore+=n;if(n>0){if(game.scoreRun?.side===side)game.scoreRun.points+=n;else game.scoreRun={side,points:n}}}
function setMoment(p,title,sub,side){game.moment={id:p?.id,title,sub,side}}
function advanceMinutes(duration){for(const side of ['home','away']){const on=new Set(game.lineups[side]),rot=rotationForSide(side);for(const p of rot.players){if(on.has(p.id)){const cap=healthMinuteCapV40(p,gameDef?.date||save?.date),raw=duration/60,played=cap<48?Math.min(raw,Math.max(0,cap-game.stats[p.id].min)):raw;game.stats[p.id].min+=played;const drain=played*(2.15+Math.max(0,82-rating(p,'stamina'))*.015);game.energy[p.id]=clamp(game.energy[p.id]-drain,28,100)}else game.energy[p.id]=clamp(game.energy[p.id]+duration/60*3.1,28,100)}}}
