function endPeriod(){if(game.period<4){const ended=game.period;addFeed(`END ${prettyPeriod(ended)} — ${game.awayScore}–${game.homeScore}.`,'home',true);game.period++;game.clock=720;game.lastMinute=-1;for(const side of ['home','away'])game.foulProtected[side]={};syncLineups(true);game.possession=game.possession==='home'?'away':'home';if(ended===2){autoCoachAdjustV41(opponentSideV41(),'HALFTIME');if(game.coachingMode==='full_auto'){autoCoachAdjustV41(userSideV41(),'HALFTIME')}else{game.halftimePending=true;stopLive()}}setMoment(topPlayers(game.possession==='home'?gameDef.home:gameDef.away,1)[0],ended===2?'HALFTIME':'NEXT QUARTER',ended===2?'Coaching adjustments underway.':`${prettyPeriod(game.period)} ready.`,game.possession)}else if(game.homeScore===game.awayScore){if(!game.regulationScore)game.regulationScore={home:game.homeScore,away:game.awayScore};game.period++;game.clock=300;game.lastMinute=-1;syncLineups(true);addFeed(`OVERTIME — tied ${game.homeScore}–${game.awayScore}.`,'home',true)}else finishGame()}
function lineFor(p,side){const s=game.stats[p.id];return {player_id:p.id,min:+s.min.toFixed(1),pts:s.pts,reb:s.reb,ast:s.ast,stl:s.stl,blk:s.blk,tov:s.tov,fgm:s.fgm,fga:s.fga,tpm:s.tpm,tpa:s.tpa,ftm:s.ftm,fta:s.fta,pf:s.pf,gs:s.gs}}
function topLine(lines){return [...lines].sort((a,b)=>(b.pts+b.reb*.7+b.ast*.8+b.stl*2+b.blk*2)-(a.pts+a.reb*.7+a.ast*.8+a.stl*2+a.blk*2))[0]}
function addSeasonLine(line,opp,res){const p=byId.get(line.player_id);if(p&&currentStatus(p)==='two_way'&&line.min>0){save.twoWayGames=save.twoWayGames||{};save.twoWayGames[p.id]=(save.twoWayGames[p.id]||0)+1}const x=save.seasonStats[line.player_id]||(save.seasonStats[line.player_id]={gp:0,gs:0,min:0,pts:0,reb:0,ast:0,stl:0,blk:0,tov:0,fgm:0,fga:0,tpm:0,tpa:0,ftm:0,fta:0,pf:0});x.gp++;for(const k of ['gs','min','pts','reb','ast','stl','blk','tov','fgm','fga','tpm','tpa','ftm','fta','pf'])x[k]+=(line[k]||0);save.gameLogs=save.gameLogs||{};const arr=save.gameLogs[line.player_id]||(save.gameLogs[line.player_id]=[]);arr.push({game_id:gameDef.id,date:gameDef.date,opp,result:res,min:line.min,pts:line.pts,reb:line.reb,ast:line.ast,stl:line.stl,blk:line.blk,fgm:line.fgm,fga:line.fga,tpm:line.tpm,tpa:line.tpa,ftm:line.ftm,fta:line.fta});if(arr.length>82)arr.shift()}
function addPlayoffLine(line,opp,res){save.playoffStats=save.playoffStats||{};const x=save.playoffStats[line.player_id]||(save.playoffStats[line.player_id]={gp:0,gs:0,min:0,pts:0,reb:0,ast:0,stl:0,blk:0,tov:0,fgm:0,fga:0,tpm:0,tpa:0,ftm:0,fta:0,pf:0});x.gp++;for(const k of ['gs','min','pts','reb','ast','stl','blk','tov','fgm','fga','tpm','tpa','ftm','fta','pf'])x[k]+=(line[k]||0);save.playoffGameLogs=save.playoffGameLogs||{};const arr=save.playoffGameLogs[line.player_id]||(save.playoffGameLogs[line.player_id]=[]);arr.push({game_id:gameDef.id,date:gameDef.date,round:gameDef.round,kind:gameDef.kind,opp,result:res,min:line.min,pts:line.pts,reb:line.reb,ast:line.ast,stl:line.stl,blk:line.blk});if(arr.length>40)arr.shift()}
