function runUntil(pred,max=1800){stopLive();let n=0;while(!game.final&&!game.halftimePending&&!game.decision&&!pred()&&n++<max)possessionEvent();render()}
function simMinute(){const p=game.period,target=Math.max(0,game.clock-60);runUntil(()=>game.period!==p||game.clock<=target)}
function simQuarter(){const p=game.period;runUntil(()=>game.period!==p||game.final)}
function simGame(){game.coachingMode='full_auto';game.halftimePending=false;game.decision=null;game.manualLineup[userSideV41()]=null;game.manualOverride[userSideV41()]=false;runUntil(()=>game.final,2400)}
function startLive(){if(game.halftimePending||game.decision)return;if(liveTimer){stopLive();render();return}const delay=speed===1?700:speed===2?360:190;liveTimer=setInterval(()=>{if(game.final||game.halftimePending||game.decision){stopLive();render();return}possessionEvent();render(false)},delay);render()}
function stopLive(){if(liveTimer){clearInterval(liveTimer);liveTimer=null}}
function livePlayer(p,side,pos){const st=game.stats[p.id],en=game.energy[p.id]||100,pf=st.pf||0;return `<div class="liveCard ${pf>=6?'foul6':pf>=5?'foul5':''}"><div class="livePhoto">${img(p)}<span class="livePos">${pos}</span><span class="liveOvr">${overall(p)}</span></div><div class="liveName">${lastName(p)}</div><div class="liveMin">${st.min.toFixed(1)} MIN · ${st.pts} PTS</div><div class="pfLine">${pf} PF${pf>=6?' · FOULED OUT':pf>=4?' · FOUL TROUBLE':''}</div><div class="energy"><i style="width:${pct(en)}%"></i></div></div>`}
function courtPanel(side){const rot=rotationForSide(side),t=team(rot.team),scheduled=scheduledLineup(side),ids=new Set(game.lineups[side]),bench=rot.players.filter(p=>!ids.has(p.id));const user=save.userTeam===t.abbr,mode=user?COACH_MODES_V41[game.coachingMode].label:'CPU COACH';return `<section class="courtPanel"><div class="courtHead"><div><span>${side==='home'?'HOME':'AWAY'} · ${t.abbr}</span><strong>${t.name}</strong></div><span>${user?'YOUR ROTATION':'CPU ROTATION'} · ${mode}</span></div><div class="fiveLive">${scheduled.map(x=>livePlayer(byId.get(x.id),side,x.pos)).join('')}</div><div class="benchStrip">${bench.map(p=>`<div class="benchChip">${img(p)}<div><b>${lastName(p)}</b><span>${game.gameInjured[p.id]?'OUT · '+game.gameInjured[p.id].name:(game.stats[p.id].pf>=6?'FOULED OUT':game.stats[p.id].min.toFixed(1)+' / '+rot.targets.get(p.id)+' MIN · '+pct(game.energy[p.id])+'% · '+game.stats[p.id].pf+' PF')}</span></div></div>`).join('')}</div></section>`}
function momentCard(){const m=game.moment,p=m?byId.get(m.id):null;if(!p)return `<div class="moment" style="--moment:#333"><div></div><div><strong>TIP OFF</strong><span>${team(gameDef.away).abbr} at ${team(gameDef.home).abbr}</span></div><em>LIVE</em></div>`;const t=team(currentTeam(p))||team(m.side==='home'?gameDef.home:gameDef.away);return `<div class="moment" style="--moment:${t.primary_color}">${img(p)}<div><strong>${m.title} · ${p.name}</strong><span>${m.sub}</span></div><em>${game.awayScore}–${game.homeScore}</em></div>`}
function feedView(){return `<div class="feed">${game.feed.slice(0,10).map(x=>`<div class="feedItem"><div class="feedClock">${prettyPeriod(x.period)} ${x.clock}</div><div class="feedText">${x.text}</div><div class="feedScore">${x.score}</div></div>`).join('')}</div>`}
function statRows(side,source=null){const rot=rotationForSide(side),data=source?new Map(source.map(x=>[x.player_id,x])):null;return rot.players.map(p=>({p,s:data?.get(p.id)||game.stats[p.id]})).sort((a,b)=>(b.s.min||0)-(a.s.min||0)).map(x=>`<div class="boxRow"><div class="boxPlayer">${img(x.p)}<b>${lastName(x.p)}</b></div><span>${(+x.s.min).toFixed(1)}</span><span>${x.s.pts}</span><span>${x.s.reb}</span><span>${x.s.ast}</span><span>${x.s.fgm}-${x.s.fga}</span></div>`).join('')}
function boxPanel(savedResult=null){const source=savedResult?.box?.[boxSide]||null;return `<section class="boxPanel"><div class="boxTabs"><button data-box="away" class="${boxSide==='away'?'active':''}">${team(gameDef.away).abbr}</button><button data-box="home" class="${boxSide==='home'?'active':''}">${team(gameDef.home).abbr}</button></div><div class="boxRow head"><div>PLAYER</div><span>MIN</span><span>PTS</span><span>REB</span><span>AST</span><span>FG</span></div>${source?statRows(boxSide,source):statRows(boxSide)}</section>`}
function gameScreen(){const h=team(gameDef.home),a=team(gameDef.away);return `<div class="scoreboard"><div class="scoreInner"><div class="scoreSide">${logo(a)}<div><span>${a.abbr}</span><b>${game.awayScore}</b></div></div><div class="clock"><span>${prettyPeriod(game.period)}</span><strong>${fmtClock(game.clock)}</strong><small>${game.possession==='home'?h.abbr:a.abbr} BALL · ${game.possessions} POS</small></div><div class="scoreSide home"><div><span>${h.abbr}</span><b>${game.homeScore}</b></div>${logo(h)}</div></div></div><div class="gameDayPrimaryZone livePrimary"><div class="gameDayPrimaryHead"><span>DO THIS NOW</span><b>LIVE GAME CONTROLS</b></div><div class="gameControls"><button class="${liveTimer?'':'live'}" id="liveBtn">${liveTimer?'PAUSE':'WATCH LIVE'}</button><button id="simMinute">SIM 1 MIN</button><button id="simQuarter">TO QTR</button></div><button class="secondary" id="finishGame">SIM FINAL</button><div class="speedRow"><button data-speed="1" class="${speed===1?'active':''}">1× LIVE</button><button data-speed="2" class="${speed===2?'active':''}">2×</button><button data-speed="4" class="${speed===4?'active':''}">4×</button></div></div>${momentCard()}${timeoutBannerV41()}${game.halftimePending?halftimePanelV41():''}${game.decision?decisionPanelV41():''}${coachDeskV41()}${courtPanel('away')}${courtPanel('home')}<div class="sectionHead"><h2>Game Feed</h2><span>LIVE COACHING · SAME POSSESSION CORE</span></div>${feedView()}<div class="sectionHead"><h2>Box Score</h2><span>LIVE MINUTES</span></div>${boxPanel()}`}
