function savedFinalScreen(r){rotations={home:runtimeRotation(gameDef.home),away:runtimeRotation(gameDef.away)};const winner=team(r.winner|| (r.home_score>r.away_score?gameDef.home:gameDef.away));return `<a class="backLink" href="index.html?continue=1&v=0.48">← GM OFFICE</a>${isCupFinal?`<div class="playoffGameBand finals cupFinalBand"><span>EMIRATES NBA CUP</span><strong>CHAMPIONSHIP FINAL</strong></div>`:isPostseason?`<div class="playoffGameBand ${gameDef.round===4?'finals':''}"><span>${postseasonLabel()}</span><strong>FINAL</strong></div>`:''}<section class="finalHero ${(isPostseason||isCupFinal)?'postseasonFinal':''}"><div class="finalTag">FINAL · SAVED RESULT${isPostseason?' · PLAYOFFS':isCupFinal?' · NBA CUP':''}</div><div class="finalScore">${r.away_score}<br>${r.home_score}</div><div class="finalWinner">${winner.name.toUpperCase()} WIN.</div></section>${r.box?`<div class="sectionHead"><h2>Final Box Score</h2><span>${isPostseason?'PLAYOFF GAME DAY':isCupFinal?'NBA CUP CHAMPIONSHIP':'GAME DAY ENGINE'}</span></div>${boxPanel(r)}`:'<div class="notice">This result was created before full box-score persistence was enabled.</div>'}<a class="primary returnBtn" href="index.html?continue=1&v=0.48">RETURN TO GM OFFICE</a>`}
function render(scrollTop=false){setColors();const root=$('#app'),sr=savedResult();if(!save||!gameDef){root.innerHTML=pregameScreen()}else if(sr&&!game){stage='final';root.innerHTML=savedFinalScreen(sr)}else if(stage==='pregame')root.innerHTML=pregameScreen();else if(stage==='game')root.innerHTML=gameScreen();else root.innerHTML=finalScreen();bind();if(scrollTop)window.scrollTo({top:0,behavior:'smooth'})}
function bind(){if(!save||!gameDef)return;if(stage==='pregame'&&!savedResult()){const w=$('#watchGame'),sm=$('#simNow');if(w)w.onclick=()=>startGame(true,false);if(sm)sm.onclick=()=>{startGame(false,true);simGame()};document.querySelectorAll('[data-coach-mode]').forEach(b=>b.onclick=()=>setCoachPrefV41('mode',b.dataset.coachMode));document.querySelectorAll('[data-rotation-plan]').forEach(b=>b.onclick=()=>setCoachPrefV41('rotationPlan',b.dataset.rotationPlan))}else if(stage==='game'){const live=$('#liveBtn'),m=$('#simMinute'),q=$('#simQuarter'),f=$('#finishGame');if(live)live.onclick=startLive;if(m)m.onclick=simMinute;if(q)q.onclick=simQuarter;if(f)f.onclick=simGame;document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>{speed=+b.dataset.speed;if(liveTimer){stopLive();startLive()}else render()});document.querySelectorAll('[data-box]').forEach(b=>b.onclick=()=>{boxSide=b.dataset.box;render()});document.querySelectorAll('[data-live-mode]').forEach(b=>b.onclick=()=>liveModeV41(b.dataset.liveMode));document.querySelectorAll('[data-coach-off]').forEach(b=>b.onclick=()=>setTacticV41('offense',b.dataset.coachOff));document.querySelectorAll('[data-coach-def]').forEach(b=>b.onclick=()=>setTacticV41('defense',b.dataset.coachDef));document.querySelectorAll('[data-coach-late]').forEach(b=>b.onclick=()=>setTacticV41('late',b.dataset.coachLate));document.querySelectorAll('[data-decision]').forEach(b=>b.onclick=()=>resolveDecisionV41(b.dataset.decision));document.querySelectorAll('[data-halftime]').forEach(b=>b.onclick=()=>continueHalftimeV41(b.dataset.halftime));if($('#callTimeout'))$('#callTimeout').onclick=()=>{callTimeoutV41(userSideV41(),'MANUAL');render()};if($('#resumeAuto'))$('#resumeAuto').onclick=resumeAutoSubsV41;if($('#makeSub'))$('#makeSub').onclick=()=>makeSubV41($('#subOut')?.value,$('#subIn')?.value);if($('#setMatchup'))$('#setMatchup').onclick=()=>setMatchupV41($('#matchDef')?.value,$('#matchTarget')?.value)}else document.querySelectorAll('[data-box]').forEach(b=>b.onclick=()=>{boxSide=b.dataset.box;render()})}
